import { Loc } from 'main.core';
import { type MenuItemOptions } from 'ui.system.menu';

import { Analytics } from 'im.v2.lib.analytics';
import { Feature, FeatureManager } from 'im.v2.lib.feature';
import { RecentMenu } from 'im.v2.lib.menu';
import { CopilotRecentService } from 'im.v2.provider.service.copilot';

export class CopilotRecentMenu extends RecentMenu
{
	getMenuItems(): MenuItemOptions[]
	{
		return [
			this.getUnreadMessageItem(),
			this.getPinMessageItem(),
			this.getAddToFolderItem(),
			this.getMuteItem(),
			this.getHideItem(),
			this.getLeaveItem(),
		];
	}

	getAddToFolderItem(): ?MenuItemOptions
	{
		if (!FeatureManager.isFeatureAvailable(Feature.copilotActive))
		{
			return null;
		}

		return super.getAddToFolderItem();
	}

	getHideItem(): MenuItemOptions
	{
		return {
			title: Loc.getMessage('IM_LIB_MENU_HIDE_MSGVER_1'),
			onClick: () => {
				this.getRecentService().hideChat(this.context.dialogId);
				Analytics.getInstance().recentContextMenu.onHide(this.context.dialogId);
				this.menuInstance.close();
			},
		};
	}

	getRecentService(): CopilotRecentService
	{
		if (!this.service)
		{
			this.service = new CopilotRecentService();
		}

		return this.service;
	}
}
